// pytypes.mjs — shared Python value wrappers and semantics helpers.
// Pure Node ESM: no imports, no JSON, no RegExp.

// ---------- helpers ----------

export function isNegativeZero(value) {
  return Object.is(value, -0);
}

// Booleans and finite integral numbers count as "int-like" in Python terms.
export function pythonIntLike(value) {
  if (typeof value === 'boolean') return true;
  return typeof value === 'number' && Number.isFinite(value) && Math.floor(value) === value;
}

function typeName(value) {
  if (value === null || value === undefined) return 'NoneType';
  if (typeof value === 'boolean') return 'bool';
  if (typeof value === 'number') return Number.isInteger(value) ? 'int' : 'float';
  if (typeof value === 'string') return 'str';
  if (Array.isArray(value)) return 'list';
  if (value instanceof PyTuple) return 'tuple';
  if (value instanceof PyFrozenSet) return 'frozenset';
  if (value instanceof PyBytes) return 'bytes';
  if (value instanceof PyComplex) return 'complex';
  if (value instanceof PyRange) return 'range';
  if (value instanceof PyDict) return 'dict';
  return typeof value;
}

// ---------- wrapper classes ----------

export class PyTuple {
  constructor(items) {
    this.items = items;
  }
}

export class PyFrozenSet {
  constructor(items) {
    // Frozensets dedupe members by Python equality.
    const deduped = [];
    for (const item of items) {
      if (!deduped.some((existing) => pythonEquals(existing, item))) deduped.push(item);
    }
    this.items = deduped;
  }
}

export class PyBytes {
  constructor(bytes) {
    this.bytes = bytes; // Uint8Array
  }
}

export class PyComplex {
  constructor(real, imag) {
    this.real = real;
    this.imag = imag;
  }
}

export class PyRange {
  constructor(start, stop, step) {
    this.start = start;
    this.stop = stop;
    this.step = step === undefined ? 1 : step;
  }
}

export class PyDict {
  // entries: iterable of [key, value] pairs, insertion order preserved.
  constructor(entries = []) {
    this.entries = [];
    for (const pair of entries) this.set(pair[0], pair[1]);
  }

  // Python dict semantics: an equal key keeps its original position/key,
  // only the value is replaced (True/1/1.0 collapse, NaN never collapses).
  set(key, value) {
    for (const pair of this.entries) {
      if (pythonEquals(pair[0], key)) {
        pair[1] = value;
        return;
      }
    }
    this.entries.push([key, value]);
  }

  getEntries() {
    return this.entries;
  }
}

// ---------- equality ----------

export function pythonEquals(a, b) {
  if (a === b) {
    // NaN !== NaN in Python; Object.is distinguishes -0, but -0 == 0 there.
    return typeof a !== 'number' || !Number.isNaN(a);
  }

  // None-like values only equal each other (handled above).
  if (a === null || a === undefined || b === null || b === undefined) return false;

  // bool/number cross-comparison: True == 1, False == 0.
  const aNum = typeof a === 'boolean' || typeof a === 'number';
  const bNum = typeof b === 'boolean' || typeof b === 'number';
  if (aNum && bNum) return Number(a) === Number(b);
  if (aNum !== bNum && (typeof a === 'string' || typeof b === 'string')) return false;
  if (typeof a === 'string' || typeof b === 'string') return false;

  // Complex: 1+0j == 1 holds in Python.
  if (a instanceof PyComplex || b instanceof PyComplex) {
    const ca = a instanceof PyComplex ? a : new PyComplex(Number(a), 0);
    const cb = b instanceof PyComplex ? b : new PyComplex(Number(b), 0);
    if ((aNum || a instanceof PyComplex) && (bNum || b instanceof PyComplex)) {
      return ca.real === cb.real && ca.imag === cb.imag;
    }
    return false;
  }

  if (Array.isArray(a) && Array.isArray(b)) {
    return a.length === b.length && a.every((item, i) => pythonEquals(item, b[i]));
  }
  if (a instanceof PyTuple && b instanceof PyTuple) {
    return a.items.length === b.items.length &&
      a.items.every((item, i) => pythonEquals(item, b.items[i]));
  }
  if (a instanceof PyBytes && b instanceof PyBytes) {
    const (x, y) = [a.bytes, b.bytes];
    if (x.length !== y.length) return false;
    for (let i = 0; i < x.length; i++) if (x[i] !== y[i]) return false;
    return true;
  }
  if (a instanceof PyFrozenSet && b instanceof PyFrozenSet) {
    return a.items.length === b.items.length &&
      a.items.every((item) => b.items.some((other) => pythonEquals(item, other)));
  }
  if (a instanceof PyDict && b instanceof PyDict) {
    if (a.entries.length !== b.entries.length) return false;
    return a.entries.every(([key, value]) => {
      for (const [bKey, bValue] of b.entries) {
        if (pythonEquals(key, bKey)) return pythonEquals(value, bValue);
      }
      return false;
    });
  }
  return false;
}

