  // -0 == 0 in Python even though Object.is tells them apart.
  if (a === b) return !(typeof a === 'number' && Number.isNaN(a));
  if (Object.is(a, b)) return true; // both NaN handled above; -0/0 falls through
  if (isNegativeZero(a) && b === 0) return true;
  if (isNegativeZero(b) && a === 0) return true;

  // None-like values only equal each other (handled above).
  if (a === null || a === undefined || b === null || b === undefined) return false;

  // bool/number cross-comparison: True == 1, False == 0.
  const aNum = typeof a === 'boolean' || typeof a === 'number';
  const bNum = typeof b === 'boolean' || typeof b === 'number';
