  if (typeof a === 'string' || typeof b === 'string') return false;

  // Complex: 1+0j == 1 holds in Python.
  if (a instanceof PyComplex || b instanceof PyComplex) {
    if (!(aNum || a instanceof PyComplex) || !(bNum || b instanceof PyComplex)) return false;
    const ca = a instanceof PyComplex ? a : new PyComplex(Number(a), 0);
    const cb = b instanceof PyComplex ? b : new PyComplex(Number(b), 0);
    return ca.real === cb.real && ca.imag === cb.imag;
  }

  if (Array.isArray(a) && Array.isArray(b)) {
    return a.length === b.length && a.every((item, i) => pythonEquals(item, b[i]));
  }
  if (a instanceof PyTuple && b instanceof PyTuple) {
    return a.items.length === b.items.length &&
      a.items.every((item, i) => pythonEquals(item, b.items[i]));
  }
  if (a instanceof PyBytes && b instanceof PyBytes) {
    const x = a.bytes;
    const y = b.bytes;
    if (x.length !== y.length) return false;
    for (let i = 0; i < x.length; i++) if (x[i] !== y[i]) return false;
    return true;
  }
  if (a instanceof PyFrozenSet && b instanceof PyFrozenSet) {
    return a.items.length === b.items.length &&
      a.items.every((item) => b.items.some((other) => pythonEquals(item, other)));
  }
  if (a instanceof PyDict && b instanceof PyDict) {
    if (a.entries.length !== b.entries.length) return false;
    return a.entries.every(([key, value]) => {
      for (const [bKey, bValue] of b.entries) {
        if (pythonEquals(key, bKey)) return pythonEquals(value, bValue);
      }
      return false;
    });
  }
  return false;
}

// ---------- ordering ----------

// Compare two strings by Unicode code points (as Python does), not UTF-16 units.
function compareCodePoints(a, b) {
  let i = 0;
  let j = 0;
  while (i < a.length && j < b.length) {
    const ca = a.codePointAt(i);
    const cb = b.codePointAt(j);
    if (ca !== cb) return ca < cb ? -1 : 1;
    i += ca > 0xffff ? 2 : 1;
    j += cb > 0xffff ? 2 : 1;
  }
  if (i < a.length) return 1;
  if (j < b.length) return -1;
  return 0;
}

function sequenceLessThan(aItems, bItems) {
  const n = Math.min(aItems.length, bItems.length);
  for (let i = 0; i < n; i++) {
    if (!pythonEquals(aItems[i], bItems[i])) return pythonLessThan(aItems[i], bItems[i]);
  }
  return aItems.length < bItems.length;
}

export function pythonLessThan(a, b) {
  const aNum = typeof a === 'boolean' || typeof a === 'number';
  const bNum = typeof b === 'boolean' || typeof b === 'number';
  if (aNum && bNum) {
    const x = Number(a);
    const y = Number(b);
    if (Number.isNaN(x) || Number.isNaN(y)) return false; // Python: NaN < x is False
    return x < y;
  }
  if (typeof a === 'string' && typeof b === 'string') return compareCodePoints(a, b) < 0;
  if (Array.isArray(a) && Array.isArray(b)) return sequenceLessThan(a, b);
  if (a instanceof PyTuple && b instanceof PyTuple) return sequenceLessThan(a.items, b.items);
  throw new TypeError(
    "'<' not supported between instances of '" + typeName(a) + "' and '" + typeName(b) + "'"
  );
}

// ---------- float repr ----------

// Split a finite, positive double into shortest-round-trip digits and decpt,
// where value === 0.d1d2... * 10^decpt (digits carry no trailing zeros).
function shortestDigits(value) {
  const s = String(value); // JS also yields the shortest round-trip decimal
  const ePos = s.indexOf('e');
  let mantissa;
  let exp;
  if (ePos >= 0) {
    mantissa = s.slice(0, ePos);
    exp = Number(s.slice(ePos + 1));
  } else {
    mantissa = s;
    exp = 0;
  }
  const dotPos = mantissa.indexOf('.');
  let intPart;
  let fracPart;
  if (dotPos >= 0) {
    intPart = mantissa.slice(0, dotPos);
    fracPart = mantissa.slice(dotPos + 1);
  } else {
    intPart = mantissa;
    fracPart = '';
  }
  let digits;
  let decpt;
  if (intPart === '0' || intPart === '') {
    // value < 1: skip leading zeros of the fraction
    let zeros = 0;
    while (zeros < fracPart.length && fracPart.charAt(zeros) === '0') zeros++;
    digits = fracPart.slice(zeros);
    decpt = exp - zeros;
  } else {
    digits = intPart + fracPart;
    decpt = exp + intPart.length;
  }
  // Strip trailing zeros; decpt is unaffected (0.1500 -> 0.15).
  let end = digits.length;
  while (end > 1 && digits.charAt(end - 1) === '0') end--;
  return { digits: digits.slice(0, end), decpt };
}

// Emulate CPython repr(float): fixed notation for -3 <= decpt <= 16,
// scientific notation outside that range, exponent at least two digits.
export function pythonFloatRepr(value) {
  if (Number.isNaN(value)) return 'nan';
  if (value === Infinity) return 'inf';
  if (value === -Infinity) return '-inf';
  if (value === 0) return isNegativeZero(value) ? '-0.0' : '0.0';

  const sign = value < 0 ? '-' : '';
  const { digits, decpt } = shortestDigits(Math.abs(value));

  if (decpt > 16 || decpt <= -4) {
    const e = decpt - 1;
    const absE = Math.abs(e);
    const expStr = (e < 0 ? '-' : '+') + (absE < 10 ? '0' + String(absE) : String(absE));
    const mantissa = digits.length > 1
      ? digits.charAt(0) + '.' + digits.slice(1)
      : digits.charAt(0);
    return sign + mantissa + 'e' + expStr;
  }
  if (decpt <= 0) {
    return sign + '0.' + '0'.repeat(-decpt) + digits;
  }
  if (decpt >= digits.length) {
    return sign + digits + '0'.repeat(decpt - digits.length) + '.0';
  }
  return sign + digits.slice(0, decpt) + '.' + digits.slice(decpt);
}

