assert(threw, 'list vs tuple TypeError');
assert(!pythonLessThan(NaN, 1) && !pythonLessThan(1, NaN), 'NaN comparisons false');

// isNegativeZero / pythonIntLike
assert(isNegativeZero(-0) && !isNegativeZero(0) && !isNegativeZero(-1), 'isNegativeZero');
assert(pythonIntLike(true) && pythonIntLike(3) && pythonIntLike(3.0) && !pythonIntLike(3.5)
  && !pythonIntLike(NaN) && !pythonIntLike(Infinity) && !pythonIntLike('3'), 'pythonIntLike');

// float repr
const cases = [
  [0, '0.0'], [-0, '-0.0'], [1, '1.0'], [-2.5, '-2.5'], [0.1, '0.1'],
  [1e15, '1000000000000000.0'], [1e16, '1e+16'], [1.5e16, '1.5e+16'],
  [1e-4, '0.0001'], [1e-5, '1e-05'], [1.234e-7, '1.234e-07'],
  [1e100, '1e+100'], [1e-100, '1e-100'], [5e-324, '5e-324'],
  [1e21, '1e+21'], [123456.789, '123456.789'], [2.0, '2.0'],
  [Infinity, 'inf'], [-Infinity, '-inf'], [NaN, 'nan'],
  [0.30000000000000004, '0.30000000000000004'],
];
for (const [v, expected] of cases) {
