function numericPow(a, b) {
  if (isIntLike(a) && isIntLike(b)) {
    const x = toBig(a);
    const y = toBig(b);
    if (y >= 0n) return x ** y;
    if (x === 0n) {
      throw pyError('ZeroDivisionError', '0.0 cannot be raised to a negative power');
    }
    return floatPow(toFloat(x), toFloat(y));
  }
  const x = toFloat(a);
  const y = toFloat(b);
  if (x === 0 && y < 0) {
    throw pyError('ZeroDivisionError', '0.0 cannot be raised to a negative power');
  }
  return floatPow(x, y);
}

function toComplex(v) {
  if (v instanceof PyComplex) return v;
  if (isNumeric(v)) return new PyComplex(toFloat(v), 0);
  return null;
}

function complexBinary(op, a, b) {
  const x = toComplex(a);
  const y = toComplex(b);
  if (x === null || y === null) throw binTypeError(op, a, b);
  if (op === '+') return new PyComplex(x.real + y.real, x.imag + y.imag);
  if (op === '-') return new PyComplex(x.real - y.real, x.imag - y.imag);
  if (op === '*') {
    return new PyComplex(
      x.real * y.real - x.imag * y.imag,
      x.real * y.imag + x.imag * y.real
    );
  }
  if (op === '/') {
    const d = y.real * y.real + y.imag * y.imag;
    if (d === 0) throw pyError('ZeroDivisionError', 'complex division by zero');
    return new PyComplex(
      (x.real * y.real + x.imag * y.imag) / d,
      (x.imag * y.real - x.real * y.imag) / d
    );
  }
  if (op === '**') {
    if (x.real === 0 && x.imag === 0) {
      if (y.imag !== 0 || y.real < 0) {
        throw pyError('ZeroDivisionError', '0.0 cannot be raised to a negative or complex power');
      }
      if (y.real === 0) return new PyComplex(1, 0);
      return new PyComplex(0, 0);
    }
    const lr = Math.log(Math.hypot(x.real, x.imag));
    const th = Math.atan2(x.imag, x.real);
    const mag = Math.exp(y.real * lr - y.imag * th);
    const ang = y.real * th + y.imag * lr;
    return new PyComplex(mag * Math.cos(ang), mag * Math.sin(ang));
  }
  throw binTypeError(op, a, b);
}

// Repetition of str/list/tuple/bytes by an int-like count; element identity is kept.
function repeatValue(seq, count, op) {
  const n = toIndex(count);
  if (n === null) {
    throw new TypeError("can't multiply sequence by non-int of type '" + typeName(count) + "'");
  }
  if (typeof seq === 'string') {
    if (n <= 0 || seq.length === 0) return '';
    try {
      return seq.repeat(n);
    } catch (e) {
      throw pyError('OverflowError', 'repeated string is too long');
    }
  }
  if (n <= 0) {
    if (Array.isArray(seq)) return [];
    if (seq instanceof PyTuple) return new PyTuple([]);
    return new PyBytes(new Uint8Array(0));
  }
  const srcItems = Array.isArray(seq) ? seq : seq instanceof PyTuple ? seq.items : null;
  if (srcItems !== null) {
    if (srcItems.length > 0 && n * srcItems.length > 2147483647) throw pyError('MemoryError', '');
    const out = [];
    for (let k = 0; k < n; k++) {
      for (let m = 0; m < srcItems.length; m++) out.push(srcItems[m]);
    }
    return Array.isArray(seq) ? out : new PyTuple(out);
  }
  // bytes
  const bytes = seq.bytes;
  if (bytes.length > 0 && n * bytes.length > 2147483647) throw pyError('MemoryError', '');
  const out = new Uint8Array(n * bytes.length);
  for (let k = 0; k < n; k++) out.set(bytes, k * bytes.length);
  return new PyBytes(out);
}

function unaryOp(op, v) {
  if (op === '-') {
    if (isBig(v)) return -v;
    if (isNum(v)) return -v;
    if (isBool(v)) return v ? -1n : 0n;
    if (v instanceof PyComplex) return new PyComplex(-v.real, -v.imag);
    throw new TypeError("bad operand type for unary -: '" + typeName(v) + "'");
  }
  // unary plus
  if (isBig(v)) return v;
  if (isNum(v)) return v;
  if (isBool(v)) return v ? 1n : 0n;
  if (v instanceof PyComplex) return v;
  throw new TypeError("bad operand type for unary +: '" + typeName(v) + "'");
}

function binaryOp(op, a, b) {
  if (a instanceof PyComplex || b instanceof PyComplex) {
    if (op === '//') throw new TypeError("can't take floor of complex instance.");
    if (op === '%') throw new TypeError("can't mod complex numbers.");
    return complexBinary(op, a, b);
  }
  if (op === '+') {
    if (typeof a === 'string' && typeof b === 'string') return a + b;
    if (Array.isArray(a) && Array.isArray(b)) return a.concat(b);
    if (a instanceof PyTuple && b instanceof PyTuple) {
      return new PyTuple(a.items.concat(b.items));
    }
    if (a instanceof PyBytes && b instanceof PyBytes) {
      return new PyBytes(concatBytes(a.bytes, b.bytes));
    }
    if (isNumeric(a) && isNumeric(b)) return numericAdd(a, b);
    throw binTypeError(op, a, b);
  }
  if (op === '-') {
    if (isNumeric(a) && isNumeric(b)) return numericSub(a, b);
    throw binTypeError(op, a, b);
  }
  if (op === '*') {
    if (isNumeric(a) && isNumeric(b)) return numericMul(a, b);
    if (isSequence(a) && (isIntLike(b) || isNum(b))) return repeatValue(a, b, op);
    if ((isIntLike(a) || isNum(a)) && isSequence(b)) return repeatValue(b, a, op);
    throw binTypeError(op, a, b);
  }
  if (op === '/' || op === '//' || op === '%' || op === '**') {
    if (isNumeric(a) && isNumeric(b)) {
      if (op === '/') return numericTrueDiv(a, b);
      if (op === '//') return numericFloorDiv(a, b);
      if (op === '%') return numericMod(a, b);
      return numericPow(a, b);
    }
    if (op === '*' === false && (isSequence(a) || isSequence(b))) {
      // fall through to generic error below
    }
    throw binTypeError(op, a, b);
  }
  throw binTypeError(op, a, b);
}

// ---------- str()/repr() ----------

function reprString(s) {
  const quote = s.indexOf("'") >= 0 && s.indexOf('"') < 0 ? '"' : "'";
  let out = quote;
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    if (ch === '\\') out += '\\\\';
    else if (ch === quote) out += '\\' + quote;
    else if (ch === '\n') out += '\\n';
    else if (ch === '\t') out += '\\t';
    else if (ch === '\r') out += '\\r';
    else if (cp < 0x20 || cp === 0x7f) out += '\\x' + hex2(cp);
    else if (cp >= 0xd800 && cp <= 0xdfff) out += '\\u' + hex4(cp);
    else out += ch;
  }
  return out + quote;
}

function reprBytes(bytes) {
  let hasSingle = false;
  let hasDouble = false;
  for (let i = 0; i < bytes.length; i++) {
    if (bytes[i] === 39) hasSingle = true;
    if (bytes[i] === 34) hasDouble = true;
  }
  const quote = hasSingle && !hasDouble ? '"' : "'";
  const qcode = quote.charCodeAt(0);
  let out = 'b' + quote;
  for (let i = 0; i < bytes.length; i++) {
    const b = bytes[i];
    if (b === 92) out += '\\\\';
    else if (b === qcode) out += '\\' + quote;
    else if (b === 9) out += '\\t';
    else if (b === 10) out += '\\n';
    else if (b === 13) out += '\\r';
    else if (b >= 32 && b < 127) out += String.fromCharCode(b);
    else out += '\\x' + hex2(b);
  }
  return out + quote;
}

// CPython renders complex parts without a trailing ".0" (repr(1j) == '1j').
function complexPartRepr(x) {
  if (Number.isNaN(x)) return 'nan';
  if (x === Infinity) return 'inf';
  if (x === -Infinity) return '-inf';
  let s = pythonFloatRepr(x);
  if (s.endsWith('.0') && s.indexOf('e') < 0) s = s.slice(0, -2);
  return s;
}

function reprComplex(c) {
  if (c.real === 0 && !isNegativeZero(c.real)) return complexPartRepr(c.imag) + 'j';
  const neg = c.imag < 0 || isNegativeZero(c.imag);
  return '(' + complexPartRepr(c.real) + (neg ? '-' : '+') +
    complexPartRepr(Math.abs(c.imag)) + 'j)';
}

function pyRepr(v) {
  if (v === null || v === undefined) return 'None';
  if (typeof v === 'boolean') return v ? 'True' : 'False';
  if (typeof v === 'bigint') return v.toString();
  if (typeof v === 'number') return pythonFloatRepr(v);
  if (typeof v === 'string') return reprString(v);
  if (Array.isArray(v)) return '[' + v.map(pyRepr).join(', ') + ']';
  if (v instanceof PyTuple) {
    if (v.items.length === 1) return '(' + pyRepr(v.items[0]) + ',)';
    return '(' + v.items.map(pyRepr).join(', ') + ')';
  }
  if (v instanceof PyDict) {
    return '{' + v.entries.map((p) => pyRepr(p[0]) + ': ' + pyRepr(p[1])).join(', ') + '}';
  }
  if (v instanceof PySet) {
    if (v.entries.length === 0) return 'set()';
    return '{' + v.entries.map(pyRepr).join(', ') + '}';
  }
  if (v instanceof PyFrozenSet) {
    if (v.items.length === 0) return 'frozenset()';
    return 'frozenset({' + v.items.map(pyRepr).join(', ') + '})';
  }
  if (v instanceof PyBytes) return reprBytes(v.bytes);
  if (v instanceof PyComplex) return reprComplex(v);
  if (v instanceof PyRange) {
    return v.step === 1
      ? 'range(' + v.start + ', ' + v.stop + ')'
      : 'range(' + v.start + ', ' + v.stop + ', ' + v.step + ')';
  }
  return String(v);
}

function pyStr(v) {
  if (typeof v === 'string') return v;
  if (v === null || v === undefined) return 'None';
  if (typeof v === 'boolean') return v ? 'True' : 'False';
  if (typeof v === 'bigint') return v.toString();
  if (typeof v === 'number') return pythonFloatRepr(v);
  return pyRepr(v);
}

// ---------- builtins ----------

function truthy(v) {
  if (v === null || v === undefined) return false;
  if (typeof v === 'boolean') return v;
  if (typeof v === 'bigint') return v !== 0n;
  if (typeof v === 'number') return v !== 0; // NaN !== 0 -> True, like Python
  if (typeof v === 'string') return v.length > 0;
  if (Array.isArray(v)) return v.length > 0;
  if (v instanceof PyTuple) return v.items.length > 0;
  if (v instanceof PyDict) return v.entries.length > 0;
  if (v instanceof PySet) return v.entries.length > 0;
  if (v instanceof PyFrozenSet) return v.items.length > 0;
  if (v instanceof PyBytes) return v.bytes.length > 0;
  if (v instanceof PyComplex) return v.real !== 0 || v.imag !== 0;
  if (v instanceof PyRange) return rangeLength(v) > 0;
  return true;
}

function rangeLength(r) {
  const start = r.start;
  const stop = r.stop;
  const step = r.step;
  if (step > 0) return stop > start ? Math.floor((stop - start + step - 1) / step) : 0;
  return stop < start ? Math.floor((start - stop - step - 1) / -step) : 0;
}

function rangeToArray(r) {
  const len = rangeLength(r);
  if (len > 10000000) throw pyError('MemoryError', '');
  const out = [];
  if (r.step > 0) {
    for (let v = r.start; v < r.stop; v += r.step) out.push(BigInt(v));
  } else {
    for (let v = r.start; v > r.stop; v += r.step) out.push(BigInt(v));
  }
  return out;
}

function itemsOf(v) {
  if (Array.isArray(v)) return v.slice();
  if (v instanceof PyTuple) return v.items.slice();
  if (v instanceof PySet) return v.entries.slice();
  if (v instanceof PyFrozenSet) return v.items.slice();
  if (v instanceof PyDict) return v.entries.map((p) => p[0]);
  if (typeof v === 'string') return Array.from(v);
  if (v instanceof PyBytes) return Array.from(v.bytes, (b) => BigInt(b));
  if (v instanceof PyRange) return rangeToArray(v);
  throw new TypeError("'" + typeName(v) + "' object is not iterable");
}

function checkArgCount(name, args, min, max, msg) {
  if (args.length < min || args.length > max) {
    throw new TypeError(msg.replace('{n}', String(args.length)));
  }
}

// Reads a run of decimal digits (with legal underscores) inside a string; does not throw.
function readDigitRun(str, j) {
  let count = 0;
  let prevDigit = false;
  while (j < str.length) {
    const c = str.charAt(j);
    if (isDigit(c)) {
      count++;
      prevDigit = true;
      j++;
    } else if (c === '_' && prevDigit && j + 1 < str.length && isDigit(str.charAt(j + 1))) {
      prevDigit = false;
      j++;
    } else {
      break;
    }
  }
  return { next: j, count };
}

function parseFloatString(s) {
  const orig = s;
  const fail = () => {
    throw pyError('ValueError', 'could not convert string to float: ' + pyRepr(orig));
  };
  let str = trimPyWs(s);
  let neg = false;
  let i = 0;
  if (str.charAt(i) === '+' || str.charAt(i) === '-') {
    neg = str.charAt(i) === '-';
    i++;
  }
  const rest = str.slice(i);
  const low = rest.toLowerCase();
  if (low === 'inf' || low === 'infinity') return neg ? -Infinity : Infinity;
  if (low === 'nan') return NaN;
  let j = 0;
  let run = readDigitRun(rest, j);
  j = run.next;
  let digits = run.count;
  if (rest.charAt(j) === '.') {
    j++;
    run = readDigitRun(rest, j);
    j = run.next;
    digits += run.count;
  }
  if (digits === 0) fail();
  if (rest.charAt(j) === 'e' || rest.charAt(j) === 'E') {
    let k = j + 1;
    if (rest.charAt(k) === '+' || rest.charAt(k) === '-') k++;
    run = readDigitRun(rest, k);
    if (run.count === 0) fail();
    j = run.next;
  }
  if (j !== rest.length) fail();
  return Number((neg ? '-' : '') + removeUnderscores(rest));
}

function parseIntString(s, base) {
  const fail = () => {
    throw pyError(
      'ValueError',
      "invalid literal for int() with base " + base + ': ' + pyRepr(s)
    );
  };
  let str = trimPyWs(s);
  let neg = false;
  let i = 0;
  if (str.charAt(i) === '+' || str.charAt(i) === '-') {
    neg = str.charAt(i) === '-';
    i++;
  }
  let radix = base;
  let hadPrefix = false;
  const low = str.slice(i).toLowerCase();
  if (base === 0) {
    if (low.startsWith('0x')) { radix = 16; hadPrefix = true; i += 2; }
    else if (low.startsWith('0o')) { radix = 8; hadPrefix = true; i += 2; }
    else if (low.startsWith('0b')) { radix = 2; hadPrefix = true; i += 2; }
    else {
      radix = 10;
      // With base 0, leading zeros are only allowed if the value is zero.
      const body = removeUnderscores(str.slice(i));
      if (body.length > 1 && body.charAt(0) === '0') fail();
    }
  } else {
    if (base === 16 && low.startsWith('0x')) { hadPrefix = true; i += 2; }
    else if (base === 8 && low.startsWith('0o')) { hadPrefix = true; i += 2; }
    else if (base === 2 && low.startsWith('0b')) { hadPrefix = true; i += 2; }
  }
  // Validate digits: single underscores between digits (leading underscore ok after a prefix).
  const body = str.slice(i);
  if (body.length === 0) fail();
  if (body.indexOf('__') >= 0) fail();
  if (body.endsWith('_')) fail();
  if (body.startsWith('_') && !hadPrefix) fail();
  let value = 0n;
  const r = BigInt(radix);
  let any = false;
  for (let k = 0; k < body.length; k++) {
    const ch = body.charAt(k);
    if (ch === '_') continue;
    const d = digitValue(ch);
    if (d < 0 || d >= radix) fail();
    value = value * r + BigInt(d);
    any = true;
  }
  if (!any) fail();
  return neg ? -value : value;
}

function parseComplexString(s) {
  const malformed = () => {
    throw pyError('ValueError', 'complex() arg is a malformed string');
  };
  let str = trimPyWs(s);
  if (str.length === 0) malformed();
  let imag = false;
  if (str.endsWith('j') || str.endsWith('J')) {
    imag = true;
    str = str.slice(0, -1);
  }
  // Find a '+'/'-' separating real and imaginary parts (not a leading sign or exponent sign).
  let split = -1;
  for (let k = 1; k < str.length; k++) {
    const ch = str.charAt(k);
    if (ch === '+' || ch === '-') {
      const prev = str.charAt(k - 1);
      if (prev !== 'e' && prev !== 'E') split = k;
    }
  }
  const part = (p) => {
    if (p === '' || p === '+') return 1;
    if (p === '-') return -1;
    try {
      return parseFloatString(p);
    } catch (e) {
      malformed();
    }
  };
  if (!imag) {
    const re = part(str);
    if (re === 1 && (str === '' || str === '+')) malformed();
    return new PyComplex(re, 0);
  }
  if (split < 0) return new PyComplex(0, part(str));
  const re = part(str.slice(0, split));
  const im = part(str.slice(split));
  return new PyComplex(re, im);
}

function utf8Encode(s) {
  const out = [];
  let pos = 0;
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    if (cp >= 0xd800 && cp <= 0xdfff) {
      throw pyError(
        'UnicodeEncodeError',
        "'utf-8' codec can't encode character '\\u" + hex4(cp) +
          "' in position " + pos + ': surrogates not allowed'
      );
    }
    if (cp < 0x80) out.push(cp);
    else if (cp < 0x800) out.push(0xc0 | (cp >> 6), 0x80 | (cp & 63));
    else if (cp < 0x10000) {
      out.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 63), 0x80 | (cp & 63));
    } else {
      out.push(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 63),
        0x80 | ((cp >> 6) & 63),
        0x80 | (cp & 63)
      );
    }
    pos++;
  }
  return new Uint8Array(out);
}

function toByteValue(v) {
  if (isBool(v)) return v ? 1 : 0;
  if (isBig(v)) {
    if (v < 0n || v > 255n) throw pyError('ValueError', 'bytes must be in range(0, 256)');
    return Number(v);
  }
  if (isNum(v) && Number.isInteger(v)) {
    if (v < 0 || v > 255) throw pyError('ValueError', 'bytes must be in range(0, 256)');
    return v;
  }
  throw new TypeError("'" + typeName(v) + "' object cannot be interpreted as an integer");
}

function biFloat(args) {
  checkArgCount('float', args, 0, 1, 'float expected at most 1 argument, got {n}');
  if (args.length === 0) return 0;
  const v = args[0];
  if (isNum(v)) return v;
  if (isBig(v)) return toFloat(v);
  if (isBool(v)) return v ? 1 : 0;
  if (typeof v === 'string') return parseFloatString(v);
  throw new TypeError(
    "float() argument must be a string or a real number, not '" + typeName(v) + "'"
  );
}

function biInt(args) {
  checkArgCount('int', args, 0, 2, 'int() takes at most 2 arguments ({n} given)');
  if (args.length === 0) return 0n;
  const v = args[0];
  if (args.length === 2) {
    if (typeof v !== 'string') {
      throw new TypeError("int() can't convert non-string with explicit base");
    }
    const b = args[1];
    const base = isBool(b) ? (b ? 1 : 0) : isBig(b) ? toIndex(b) : isNum(b) && Number.isInteger(b) ? b : null;
    if (base === null) {
      throw new TypeError("'" + typeName(b) + "' object cannot be interpreted as an integer");
    }
    if (base !== 0 && (base < 2 || base > 36)) {
      throw pyError('ValueError', 'int() base must be >= 2 and <= 36, or 0');
    }
    return parseIntString(v, base);
  }
  if (isBig(v)) return v;
  if (isBool(v)) return v ? 1n : 0n;
  if (isNum(v)) {
    if (Number.isNaN(v)) throw pyError('ValueError', 'cannot convert float NaN to integer');
    if (!Number.isFinite(v)) {
      throw pyError('OverflowError', 'cannot convert float infinity to integer');
    }
    return BigInt(Math.trunc(v));
  }
  if (typeof v === 'string') return parseIntString(v, 10);
  throw new TypeError(
    "int() argument must be a string, a bytes-like object or a real number, not '" +
      typeName(v) + "'"
  );
}

function biStr(args) {
  checkArgCount('str', args, 0, 1, 'str() takes at most 1 argument ({n} given)');
  if (args.length === 0) return '';
  return pyStr(args[0]);
}

function biBool(args) {
  checkArgCount('bool', args, 0, 1, 'bool expected at most 1 argument, got {n}');
  if (args.length === 0) return false;
  return truthy(args[0]);
}

function biLen(args) {
  checkArgCount('len', args, 1, 1, 'len() takes exactly one argument ({n} given)');
  const v = args[0];
  if (typeof v === 'string') return Array.from(v).length;
  if (Array.isArray(v)) return v.length;
  if (v instanceof PyTuple) return v.items.length;
  if (v instanceof PyDict) return v.entries.length;
  if (v instanceof PySet) return v.entries.length;
  if (v instanceof PyFrozenSet) return v.items.length;
  if (v instanceof PyBytes) return v.bytes.length;
  if (v instanceof PyRange) return rangeLength(v);
  throw new TypeError("object of type '" + typeName(v) + "' has no len()");
}

function biTuple(args) {
  checkArgCount('tuple', args, 0, 1, 'tuple expected at most 1 argument, got {n}');
  if (args.length === 0) return new PyTuple([]);
  return new PyTuple(itemsOf(args[0]));
}

function biList(args) {
  checkArgCount('list', args, 0, 1, 'list expected at most 1 argument, got {n}');
  if (args.length === 0) return [];
  return itemsOf(args[0]);
}

function biSet(args) {
  checkArgCount('set', args, 0, 1, 'set expected at most 1 argument, got {n}');
  if (args.length === 0) return new PySet();
  return new PySet(itemsOf(args[0]));
}

function biFrozenset(args) {
  checkArgCount('frozenset', args, 0, 1, 'frozenset expected at most 1 argument, got {n}');
  if (args.length === 0) return new PyFrozenSet([]);
  return new PyFrozenSet(itemsOf(args[0]));
}

function biBytes(args) {
  checkArgCount('bytes', args, 0, 3, 'bytes() takes at most 3 arguments ({n} given)');
  if (args.length === 0) return new PyBytes(new Uint8Array(0));
  const v = args[0];
  if (args.length >= 2) {
    if (typeof v !== 'string') throw new TypeError('encoding without a string argument');
    const enc = typeof args[1] === 'string' ? args[1].toLowerCase() : '';
    if (enc === 'utf-8' || enc === 'utf8') return new PyBytes(utf8Encode(v));
    if (enc === 'ascii') {
      const out = new Uint8Array(v.length);
      for (let i = 0; i < v.length; i++) {
        const c = v.charCodeAt(i);
        if (c > 127) {
          throw pyError(
            'UnicodeEncodeError',
            "'ascii' codec can't encode character in position " + i + ': ordinal not in range(128)'
          );
        }
        out[i] = c;
      }
      return new PyBytes(out);
    }
    throw pyError('LookupError', 'unknown encoding: ' + args[1]);
  }
  if (typeof v === 'string') throw new TypeError('string argument without an encoding');
  if (v instanceof PyBytes) return new PyBytes(new Uint8Array(v.bytes));
  if (isIntLike(v)) {
    const n = toIndex(v);
    if (n < 0) throw pyError('ValueError', 'negative count');
    return new PyBytes(new Uint8Array(n));
  }
  if (Array.isArray(v) || v instanceof PyTuple || v instanceof PySet ||
      v instanceof PyFrozenSet || v instanceof PyRange) {
    const items = itemsOf(v);
    const out = new Uint8Array(items.length);
    for (let i = 0; i < items.length; i++) out[i] = toByteValue(items[i]);
    return new PyBytes(out);
  }
  throw new TypeError("'" + typeName(v) + "' object is not iterable");
}

function biComplex(args) {
  checkArgCount('complex', args, 0, 2, 'complex() takes at most 2 arguments ({n} given)');
  if (args.length === 0) return new PyComplex(0, 0);
  const a = args[0];
  if (args.length === 2) {
    if (typeof a === 'string') {
      throw new TypeError("complex() can't take second arg if first is a string");
    }
    const x = toComplex(a);
    const y = toComplex(args[1]);
    if (x === null || y === null || typeof args[1] === 'string') {
      throw new TypeError('complex() argument must be a string or a number');
    }
    // complex(a, b) == a + b * 1j
    return new PyComplex(x.real - y.imag, x.imag + y.real);
  }
  if (typeof a === 'string') return parseComplexString(a);
  const x = toComplex(a);
  if (x === null) {
    throw new TypeError(
      "complex() argument must be a string or a number, not '" + typeName(a) + "'"
    );
  }
  return new PyComplex(x.real, x.imag);
}

function biRange(args) {
  checkArgCount('range', args, 1, 3,
    args.length === 0 ? 'range expected at least 1 argument, got 0'
      : 'range expected at most 3 arguments, got {n}');
  const toIdx = (v) => {
    if (isBool(v)) return v ? 1 : 0;
    if (isBig(v)) return Number(v);
    if (isNum(v) && Number.isInteger(v)) return v;
    throw new TypeError("'" + typeName(v) + "' object cannot be interpreted as an integer");
  };
  let start;
  let stop;
  let step = 1;
  if (args.length === 1) {
    start = 0;
    stop = toIdx(args[0]);
  } else {
    start = toIdx(args[0]);
    stop = toIdx(args[1]);
    if (args.length === 3) step = toIdx(args[2]);
  }
  if (step === 0) throw pyError('ValueError', 'range() arg 3 must not be zero');
  return new PyRange(start, stop, step);
}

const BUILTINS = {
  float: biFloat,
  int: biInt,
  str: biStr,
  bool: biBool,
  len: biLen,
  tuple: biTuple,
  list: biList,
  set: biSet,
  frozenset: biFrozenset,
  bytes: biBytes,
  complex: biComplex,
  range: biRange,
};

// ---------- parser / evaluator ----------

export function parsePythonExpression(source) {
  if (typeof source !== 'string') {
    throw new TypeError('parsePythonExpression() argument must be a string');
  }
  const tokens = tokenize(source);
  let pos = 0;

  const peek = () => tokens[pos];
  const isOp = (v) => peek().t === 'op' && peek().v === v;
  const eatOp = (v) => {
    if (isOp(v)) {
      pos++;
      return true;
    }
    return false;
  };
  const expectOp = (v) => {
    if (!eatOp(v)) throw new SyntaxError('invalid syntax');
  };

  // expr (',' expr)* [','] — a trailing comma or 2+ items make a tuple.
  function parseTestlist(atEof) {
    const first = parseExpr();
    if (!isOp(',')) return first;
    const items = [first];
    while (eatOp(',')) {
      if (atEof ? peek().t === 'eof' : isOp(')')) break;
      items.push(parseExpr());
    }
    return new PyTuple(items);
  }

  function parseExpr() {
    return parseAddSub();
  }

  function parseAddSub() {
    let left = parseMulDiv();
    while (true) {
      if (eatOp('+')) left = binaryOp('+', left, parseMulDiv());
      else if (eatOp('-')) left = binaryOp('-', left, parseMulDiv());
      else return left;
    }
  }

  function parseMulDiv() {
    let left = parseUnary();
    while (true) {
      if (eatOp('*')) left = binaryOp('*', left, parseUnary());
      else if (eatOp('/')) left = binaryOp('/', left, parseUnary());
      else if (eatOp('//')) left = binaryOp('//', left, parseUnary());
      else if (eatOp('%')) left = binaryOp('%', left, parseUnary());
      else return left;
    }
  }

  // Python precedence: unary binds looser than ** on its left (-2**2 == -4),
  // but **'s right operand is itself a unary expression (2**-2 == 0.25).
  function parseUnary() {
    if (eatOp('-')) return unaryOp('-', parseUnary());
    if (eatOp('+')) return unaryOp('+', parseUnary());
    return parsePower();
  }

  function parsePower() {
    const base = parseAtomExpr();
    if (eatOp('**')) return binaryOp('**', base, parseUnary());
    return base;
  }

  function parseAtomExpr() {
    if (peek().t === 'name') {
      const name = peek().v;
      pos++;
      if (name === 'None' || name === 'True' || name === 'False') {
        const v = name === 'None' ? null : name === 'True';
        if (isOp('(')) {
          throw new TypeError(
            "'" + (name === 'None' ? 'NoneType' : 'bool') + "' object is not callable"
          );
        }
        return v;
      }
      if (isOp('(')) return parseCall(name);
      if (BUILTINS[name]) {
        throw pyError('NameError', "builtin '" + name + "' cannot be used as a value");
      }
      throw pyError('NameError', "name '" + name + "' is not defined");
    }
    const v = parseAtom();
    if (isOp('(')) {
      throw new TypeError("'" + typeName(v) + "' object is not callable");
    }
    return v;
  }

  function parseCall(name) {
    expectOp('(');
    const args = [];
    if (!eatOp(')')) {
      while (true) {
        if (peek().t === 'name' && tokens[pos + 1] && tokens[pos + 1].t === 'op' &&
            tokens[pos + 1].v === '=') {
          throw new SyntaxError('keyword arguments are not supported');
        }
        args.push(parseExpr());
        if (eatOp(',')) {
          if (eatOp(')')) break;
          continue;
        }
        expectOp(')');
        break;
      }
    }
    const fn = BUILTINS[name];
    if (!fn) throw pyError('NameError', "name '" + name + "' is not defined");
    return fn(args);
  }

  function parseAtom() {
    const tok = peek();
    if (tok.t === 'int' || tok.t === 'float' || tok.t === 'complex') {
      pos++;
      return tok.v;
    }
    if (tok.t === 'str' || tok.t === 'bytes') {
      pos++;
      // Adjacent literal concatenation: 'a' "b" -> 'ab'.
      let acc = tok;
      while (peek().t === 'str' || peek().t === 'bytes') {
        const nt = peek();
        pos++;
        if ((acc.t === 'bytes') !== (nt.t === 'bytes')) {
          throw new SyntaxError('cannot mix bytes and nonbytes literals');
        }
        acc = acc.t === 'bytes'
          ? { t: 'bytes', v: concatBytes(acc.v, nt.v) }
          : { t: 'str', v: acc.v + nt.v };
      }
      return acc.t === 'bytes' ? new PyBytes(acc.v) : acc.v;
    }
    if (isOp('(')) {
      pos++;
      if (eatOp(')')) return new PyTuple([]);
      const val = parseTestlist(false);
      expectOp(')');
      return val;
    }
    if (isOp('[')) {
      pos++;
      const items = [];
      if (!eatOp(']')) {
        while (true) {
          items.push(parseExpr());
          if (eatOp(',')) {
            if (eatOp(']')) break;
            continue;
          }
          expectOp(']');
          break;
        }
      }
      return items;
    }
    if (isOp('{')) {
      pos++;
      if (eatOp('}')) return new PyDict();
      const first = parseExpr();
      if (eatOp(':')) {
        const d = new PyDict();
        d.set(first, parseExpr());
        while (eatOp(',')) {
          if (eatOp('}')) return d;
          const k = parseExpr();
          expectOp(':');
          d.set(k, parseExpr());
        }
        expectOp('}');
        return d;
      }
      const items = [first];
      while (eatOp(',')) {
        if (isOp('}')) break;
        items.push(parseExpr());
      }
      expectOp('}');
      return new PySet(items);
    }
    throw new SyntaxError('invalid syntax');
  }

  const result = parseTestlist(true);
  if (peek().t !== 'eof') throw new SyntaxError('invalid syntax');
  return result;
}

